<?php
namespace App\Jobs;use App\Services\OperationalMetrics;use App\Domain\Imports\{ChunkStatus,ImportStatus,SourceReaderFactory};use App\Models\{ImportChunk,ImportExecution};use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Support\Facades\{DB,Storage};use RuntimeException;
final class PlanImportExecution implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=3;public function __construct(public string $executionId){}
 public function handle(SourceReaderFactory $factory,OperationalMetrics $metrics):void{$execution=ImportExecution::with('import')->findOrFail($this->executionId);if($execution->cancel_requested_at)return;try{$stream=Storage::disk(config('filesystems.default'))->readStream($execution->import->storage_key);if(!is_resource($stream))throw new RuntimeException('Unable to read import object');}catch(\Throwable $e){$metrics->storageFailure($execution->import->organization_id);throw $e;}try{$ranges=$factory->make($execution->import->source_type)->plan($stream,(int)$execution->chunk_size,$execution->import->source_options_json??[]);}finally{fclose($stream);}DB::transaction(function()use($execution,$ranges){foreach($ranges as $i=>$range)ImportChunk::firstOrCreate(['execution_id'=>$execution->id,'chunk_index'=>$i],['range_metadata_json'=>$range,'status'=>ChunkStatus::Pending]);$e=ImportExecution::lockForUpdate()->findOrFail($execution->id);if($e->cancel_requested_at){$e->update(['status'=>ImportStatus::Cancelled,'completed_at'=>now()]);return;}$e->update(['status'=>ImportStatus::Processing,'started_at'=>$e->started_at??now()]);DB::afterCommit(function()use($execution){$execution->chunks()->where('status',ChunkStatus::Pending->value)->orderBy('chunk_index')->pluck('id')->each(fn($id)=>ProcessImportChunk::dispatch($id)->onQueue('imports'));});},3);}
 public function failed(?\Throwable $e):void{ImportExecution::whereKey($this->executionId)->update(['status'=>ImportStatus::Failed,'completed_at'=>now()]);}}
